* { box-sizing: border-box; }
body { margin: 0; font-family: system-ui, -apple-system, 'Segoe UI', sans-serif; background: #f6efe3; color: #33302a; }
#root { min-height: 100vh; }
.page { max-width: 1280px; margin: 0 auto; padding: 14px 16px 30px; }
.topbar { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }
h1 { font-size: 26px; margin: 0; letter-spacing: -0.5px; }
.sub { margin: 2px 0 0; color: #7a6a55; font-size: 14px; }
.dot { display: inline-block; width: 10px; height: 10px; border-radius: 50%; }
.dot.blue { background: #2f6fe4; } .dot.red { background: #e5484d; } .dot.green { background: #3d9950; }
.transport { display: flex; gap: 8px; }
button { border: 1px solid #d8c9ae; background: #fff; border-radius: 10px; padding: 8px 14px; cursor: pointer; font-size: 14px; }
button:hover { background: #fff7e8; }
button.go { background: #2f7d3b; color: #fff; border-color: #2f7d3b; }
button.warn { background: #e5a13d; color: #fff; border-color: #e5a13d; }
.presets { display: flex; gap: 8px; margin: 10px 0; flex-wrap: wrap; }
.presets button.active { background: #7c5cff; color: #fff; border-color: #7c5cff; }
.grid { display: grid; grid-template-columns: 1.25fr 0.85fr; gap: 12px; }
.card { background: #fffdf8; border: 1px solid #e7d9bd; border-radius: 16px; padding: 12px; box-shadow: 0 4px 18px rgba(120,90,40,0.08); }
.worldCard { grid-row: span 2; }
.worldCanvas { width: 100%; height: 520px; border-radius: 12px; display: block; touch-action: none; cursor: grab; }
.chartCanvas { width: 100%; display: block; border: 1px solid #eee; border-radius: 10px; }
.inspector { margin-top: 8px; background: #faf3e5; border-radius: 10px; padding: 8px 10px; font-size: 13px; min-height: 64px; }
.inspGrid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 8px; }
.ebar { height: 10px; background: #e8dcc3; border-radius: 6px; overflow: hidden; margin-bottom: 4px; }
.efill { height: 100%; background: linear-gradient(90deg, #7ed957, #2f9e44); }
.hint { color: #8a7a5f; }
.legend { display: flex; gap: 14px; font-size: 12px; color: #7a6a55; margin-top: 6px; flex-wrap: wrap; }
.sw { display: inline-block; width: 12px; height: 12px; border-radius: 4px; margin-right: 4px; }
.sw.b { background: #5aa9ff; } .sw.r { background: #ff5d6c; } .sw.g { background: #7ed957; }
.controls h2, .charts h2 { margin: 2px 0 8px; font-size: 16px; }
.controls { max-height: 900px; overflow: auto; }
.group h3 { font-size: 12px; text-transform: uppercase; letter-spacing: 1px; color: #a08c66; margin: 10px 0 4px; }
.slider { display: block; font-size: 13px; margin: 6px 0; }
.slider span { display: flex; justify-content: space-between; }
.slider input { width: 100%; accent-color: #7c5cff; }
.charts { grid-column: 2; }
.two { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 8px; }
.two h3, .summary h3 { font-size: 13px; margin: 6px 0; color: #7a6a55; }
.summary ul { margin: 4px 0; padding-left: 18px; font-size: 13px; }
.stats { font-size: 12px; color: #8a7a5f; }
footer { margin-top: 10px; font-size: 12px; color: #a08c66; text-align: center; }
@media (max-width: 980px) { .grid { grid-template-columns: 1fr; } .charts { grid-column: 1; } .worldCanvas { height: 420px; } }

