node -e '
const S = require("/tmp/sim.cjs");
const w = S.createWorld({...S.DEFAULTS, seed: 314});
const acts = {};
for (let i = 0; i < 1500; i++) {
  S.stepWorld(w);
  if (i % 150 === 0) {
    const b = w.blobs.filter(x=>x.kind==="blue");
    const e = b.length ? (b.reduce((a,x)=>a+x.energy,0)/b.length).toFixed(1) : "-";
    const a = {};
    b.forEach(x=>a[x.action]=(a[x.action]||0)+1);
    console.log(`t=${w.tick} nb=${b.length} nr=${w.blobs.filter(x=>x.kind==="red").length} avgE=${e} fruit=${w.trees.reduce((a,t)=>a+t.fruit,0).toFixed(1)} acts=${JSON.stringify(a)} eaten=${w.cumEaten}`);
  }
}'

